namespace Meziantou.Framework.Imaging.Formats;

/// <summary>Immutable settings of tiled OpenEXR output (<see cref="OpenExrEncoder.Tiling"/>): the tile size and the resolution levels.</summary>
/// <remarks>
/// <para>
/// Each tile is a chunk compressed on its own; a tile at the right or bottom edge of a level is clipped to the level.
/// </para>
/// <para>
/// The levels below the full resolution (<see cref="OpenExrLevelMode.MipmapLevels"/>, <see cref="OpenExrLevelMode.RipmapLevels"/>)
/// are generated by the encoder: each level is the area average of the previous one (a box filter that weights each
/// source pixel by the part of it the destination pixel covers), computed on the samples the file stores, which are the
/// colors premultiplied by alpha. A mipmap level comes from the previous mipmap level; a ripmap level from the level on its
/// left, or, in the first column, from the level above it. The samples of a level are the average of the samples the file stores for its parent level, rounded to the sample type.
/// </para>
/// </remarks>
public sealed class OpenExrTiling
{
    /// <summary>Gets the width of a tile, in pixels. Defaults to 64.</summary>
    /// <exception cref="ArgumentOutOfRangeException">The value is less than 1.</exception>
    public int TileWidth
    {
        get;
        init
        {
            ArgumentOutOfRangeException.ThrowIfLessThan(value, 1);
            field = value;
        }
    } = 64;

    /// <summary>Gets the height of a tile, in pixels. Defaults to 64.</summary>
    /// <exception cref="ArgumentOutOfRangeException">The value is less than 1.</exception>
    public int TileHeight
    {
        get;
        init
        {
            ArgumentOutOfRangeException.ThrowIfLessThan(value, 1);
            field = value;
        }
    } = 64;

    /// <summary>Gets the resolution levels the file stores. Defaults to <see cref="OpenExrLevelMode.OneLevel"/>.</summary>
    /// <exception cref="ArgumentOutOfRangeException">The value is not a defined <see cref="OpenExrLevelMode"/>.</exception>
    public OpenExrLevelMode LevelMode
    {
        get;
        init
        {
            if (!Enum.IsDefined(value))
                throw new ArgumentOutOfRangeException(nameof(value), value, "The level mode is not valid.");

            field = value;
        }
    }

    /// <summary>Gets how the sizes of the levels are rounded. Defaults to <see cref="OpenExrLevelRounding.Down"/>.</summary>
    /// <exception cref="ArgumentOutOfRangeException">The value is not a defined <see cref="OpenExrLevelRounding"/>.</exception>
    public OpenExrLevelRounding LevelRounding
    {
        get;
        init
        {
            if (!Enum.IsDefined(value))
                throw new ArgumentOutOfRangeException(nameof(value), value, "The level rounding is not valid.");

            field = value;
        }
    }
}
